export function gradeAnswers(questions, answers) {
    if (answers.length !== questions.length || questions.some((question, i) => !Number.isInteger(answers[i]) || answers[i] < 0 || answers[i] >= question.options.length)) {
        throw new Error('Jawab semua soal sebelum mengumpulkan.');
    }
    const correct = questions.filter((question, i) => question.answer === answers[i]).length;
    return { correct, total: questions.length, percent: Math.round(correct / questions.length * 100) };
}
